def label(text: str) -> tuple[str, ...]:
    """A key, code or identifier as its words and numbers, for comparing how two pages write it."""
    parts = re.findall(r"[^\W_]+", text.casefold())
    return tuple(part.lstrip("0") or "0" if part.isdigit() else part for part in parts)


def same_label(a: str, b: str) -> bool:
    """Whether two pages mean the same key: equal once punctuation, case and leading zeros are ignored, or one is
    the other with words in front ("Rev. C" and "C", "Position 01.02" and "1.2")."""
    x, y = label(a), label(b)
    if not x or not y:
        return False
    short, long = sorted((x, y), key=len)
    lead = long[:len(long) - len(short)]
    return long[len(lead):] == short and all(part.isalpha() for part in lead)

