    // every upload slot is taken for a moment: that costs the team nothing, so the same package goes again
    if (response.status === 429 && attempt < UPLOAD_BUSY_TRIES && text.includes(UPLOAD_BUSY)) {
      const after = Number(response.headers.get("retry-after"))
      await sleep((Number.isFinite(after) && after > 0 ? Math.min(after, 5) : 2) * 1000 + Math.random() * 1000)
      continue
    }
    throw await responseError(response, text)
