const getJson = async (ctx, path, options) => (await request(ctx, "GET", path, options)).json()

/** A JSON call whose answer the caller reads whatever its status: the sign-in endpoints. */
async function send(api, method, path, { key, body } = {}) {
  const headers = { "user-agent": USER_AGENT, accept: "application/json" }
  if (key) headers["x-api-key"] = key
  if (body !== undefined) headers["content-type"] = "application/json"
  try {
    return await fetch(`${api}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    })
  } catch (error) {
    throw new CliError(EXIT.failure, `Cannot reach ${api}: ${error.cause?.message ?? error.message}`)
  }
}
