async function exchange(api, { code, verifier, answer }) {
  let response
  try {
    response = await send(api, "POST", "/v1/cli/token", { body: { code, code_verifier: verifier } })
  } catch (error) {
    answer(502, "Sign-in failed: the platform could not be reached. Return to your terminal.")
    throw error
  }
  if (!response.ok) {
    answer(400, "Sign-in failed. Return to your terminal for the reason.")
    throw await responseError(response)
  }
  const issued = await response.json()
  answer(200, "Signed in. You can close this tab.")
  return issued
}

/**
 * The browser first. The device code is the fallback: at once when no browser opens here, else after
 * ATIRA_LOGIN_TIMEOUT_MS, with the browser still welcome to finish first.
 */
async function browserLogin(api, label, device) {
  const loopback = await startLoopback(api, label)
  const controller = new AbortController()
  let timer
  try {
    progress(`Sign in to ${api} in your browser. If it does not open, visit:`)
    progress(`  ${loopback.link}`)
    const opened = await openBrowser(loopback.link)
    let fallBack
    const fallback = new Promise((resolve) => {
      fallBack = resolve
    })
    if (opened === "failed") {
      // no browser on this computer: its 127.0.0.1 cannot be reached from another one
      loopback.close()
      fallBack("failed")
    } else {
      progress("Waiting for approval in the browser (Ctrl-C to cancel).")
      timer = setTimeout(() => fallBack("timeout"), Number(process.env.ATIRA_LOGIN_TIMEOUT_MS) || 120_000)
    }
    const viaDevice = fallback.then((reason) => {
      progress(
        reason === "failed"
          ? "The browser could not be opened here. Sign in with a code instead."
          : "No answer from the browser yet. You can also sign in with a code.",
      )
      printDevice(device)
      return pollDevice(api, device, controller.signal)
    })
    const viaBrowser =
      opened === "failed" ? new Promise(() => {}) : loopback.callback.then((code) => exchange(api, code))
    return await Promise.race([viaBrowser, viaDevice])
  } finally {
    clearTimeout(timer)
    controller.abort()
    loopback.close()
  }
}

