/** A run id from a run_, reh_ (test run) or sub_ (submission: its latest run) id. */
async function mcpRunId(ctx, id) {
  if (typeof id === "string" && id.startsWith("reh_")) return rehearsalRun(ctx, id)
  if (typeof id === "string" && id.startsWith("sub_")) return submissionRun(ctx, id)
  if (typeof id === "string" && id.startsWith("run_")) return id
  throw new CliError(EXIT.usage, `Expected a run (run_...), test run (reh_...) or submission (sub_...) id, not ${id}`)
