/** The signed-in context: tools that act for the team need it. */
function signedIn() {
  const ctx = context()
  if (!ctx.key) throw new CliError(EXIT.auth, "Not signed in: run `atira login` in a terminal, or set ATIRA_TOKEN.")
  return ctx
}

/** One page of a run's log lines from GET /v1/runs/:id/logs/query. */
function logPage(ctx, runId, query) {
  const params = new URLSearchParams()
  for (const [name, value] of Object.entries(query))
    if (value !== undefined && value !== null && value !== "") params.set(name, String(value))
  return getJson(ctx, `/v1/runs/${enc(runId)}/logs/query?${params}`)
}

