async function allLogLines(ctx, runId, query, max = 20_000) {
  const lines = []
  let after
  for (;;) {
    const page = await logPage(ctx, runId, { ...query, limit: 1000, after })
    lines.push(...page.lines)
    if (!page.next || lines.length >= max) return { lines: byTime(lines), complete: !page.next }
    after = page.next
  }
}

